import{_ as e,o as t,c as s,a2 as i}from"./chunks/framework.BfWdyVj4.js";const m=JSON.parse('{"title":"Sums, words and facts","description":"","frontmatter":{},"headers":[],"relativePath":"features/facts.md","filePath":"features/facts.md","lastUpdated":1793093713000}'),o={name:"features/facts.md"};function r(n,a,d,h,c,l){return t(),s("div",null,[...a[0]||(a[0]=[i('<h1 id="sums-words-and-facts" tabindex="-1">Sums, words and facts <a class="header-anchor" href="#sums-words-and-facts" aria-label="Permalink to &quot;Sums, words and facts&quot;">​</a></h1><p>So the assistant doesn&#39;t do maths in its head or guess at facts, it has tools for them.</p><h2 id="sums" tabindex="-1">Sums <a class="header-anchor" href="#sums" aria-label="Permalink to &quot;Sums&quot;">​</a></h2><p><code>calculate</code> works sums out exactly: + − × ÷, powers, brackets, roots and a few functions. The sum is parsed, never run as code.</p><h2 id="units" tabindex="-1">Units <a class="header-anchor" href="#units" aria-label="Permalink to &quot;Units&quot;">​</a></h2><p><code>convert_units</code> converts length, weight, volume (British pints and gallons, US cups), temperature, speed, time and area.</p><h2 id="words" tabindex="-1">Words <a class="header-anchor" href="#words" aria-label="Permalink to &quot;Words&quot;">​</a></h2><p><code>dictionary</code> says what a word or phrase means, from <a href="https://en.wiktionary.org" target="_blank" rel="noreferrer">Wiktionary</a>: its meanings by part of speech, with an example sentence where there is one. A misspelt word gets the words they probably meant, so it helps with spelling too.</p><h2 id="wikipedia" tabindex="-1">Wikipedia <a class="header-anchor" href="#wikipedia" aria-label="Permalink to &quot;Wikipedia&quot;">​</a></h2><p><code>wikipedia</code> looks things up on Wikipedia, or on <a href="https://simple.wikipedia.org" target="_blank" rel="noreferrer">Simple English Wikipedia</a> for children. It gives the best match&#39;s summary, its picture (which <code>show_on_screen</code> accepts) and other matches, or with <code>more</code>, the article itself.</p><h2 id="wikidata" tabindex="-1">Wikidata <a class="header-anchor" href="#wikidata" aria-label="Permalink to &quot;Wikidata&quot;">​</a></h2><p><code>wikidata</code> gives exact facts from <a href="https://www.wikidata.org" target="_blank" rel="noreferrer">Wikidata</a>: population, area, capital, birthdays, heights, atomic numbers, boiling points, distance from Earth and so on. It skips names and disambiguation pages, and says when the name could mean something else.</p><p>The dictionary, Wikipedia and Wikidata are off with the grown-ups&#39; &quot;Look things up online&quot; switch.</p>',13)])])}const u=e(o,[["render",r]]);export{m as __pageData,u as default};
